@push('scripts')<script>(()=>{const toggle=document.querySelector('[data-consultation-toggle]');if(!toggle)return;const link=document.querySelector('[data-visa-checkout]'),row=document.querySelector('[data-consultation-row]'),total=document.querySelector('[data-visa-grand-total]');const base={{ $visaTotal['amount_minor'] }},fee={{ $consultationTotal['amount_minor'] }},symbol=@json($symbol);const money=v=>symbol+(v/100).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});toggle.onchange=()=>{row.classList.toggle('d-none',!toggle.checked);total.textContent=money(base+(toggle.checked?fee:0));const url=new URL(link.href);if(toggle.checked)url.searchParams.set('consultation','1');else url.searchParams.delete('consultation');link.href=url;};})();</script>@endpush
